def fizz_buzz(n):
    def divisible(value, d):
        while value > 0:
            value -= d
        return value == 0
    result = []
    for i in range(1, n + 1):
        if divisible(i, 15):
            result.append("FizzBuzz")
        elif divisible(i, 3):
            result.append("Fizz")
        elif divisible(i, 5):
            result.append("Buzz")
        else:
            result.append(str(i))
    return result
